INSERT INTO feature VALUES('runtime-lam','runtime','The runtime''s regions as a LAM','compiled-runtime','partial','notable',NULL,'A run''s values live in a heap region, its bodies'' windows in a window region and its continuations in a frame region. The heap and the window region each reserve address space for the invocation''s one memory bound, `--memory` or the host''s available memory, up to the region''s share of the process''s address space, and commit it by chunks whose sum stays within the bound; the frame region is allocated at its fixed bound once per thread. The regions of a process reserve together at most a quarter of the space that one probe mapping reads, held in one account, and a region''s share is that quarter divided by twice the host''s width. A run that would pass a bound declines and names the region that asked, and a stop at a share names the share, the account''s remainder and the space. The regions are a location-addressable memory in the sense of Rainey et al. (LoCalMem, ICFP 2026): a match reads a value where it stands, a copy is its address and one owner more, and an outcome leaves for the caller''s store each object once, sharing kept; the store it reaches appends, never changes a value at its address and never recycles one. The regions depart from it where a freed block is reused and where a block one owner holds is rebuilt in place, the rebuild the exclusivity conjecture says answers as the copy: an update through an exclusive view answers as its copy on both tiers, and a copy taken before it keeps its value. The update rebuilt in the held value''s own block, which takes a fresh block because the held cell keeps its owner while the view is out, is owed (#3205).','runtime-emitter core-sequent','corpus/ledger/features/runtime-lam.gandr corpus/model/runtime/exclusive-update.gandr crates/runtime-emitter/src/run.rs crates/runtime-emitter/src/regions.rs crates/runtime-stencils/tests/count.rs crates/runtime-stencils/tests/exits.rs','corpus/ledger/features/runtime-lam.gandr','#3205');
